import random,itertools
from offline_discovery.exact_keys import ExactKeySpace, interval_without_point

def brute(patterns):
    s=set()
    for pat in patterns:
        domains=[]
        for lo,hi in pat:
            vals=[v for v in range(lo,hi+1) if v!=1514]
            domains.append(vals)
        if any(not d for d in domains): continue
        for k in itertools.product(*domains): s.add(k)
    return s

for trial in range(2000):
    L=random.randint(1,4)
    n=random.randint(0,6)
    pats=[]
    for _ in range(n):
        pat=[]
        for j in range(L):
            lo=random.randint(0,8)
            hi=random.randint(lo,8)
            # occasionally bigger around 1514
            if random.random()<.2:
                lo=random.choice([1500,1513,1514,1515])
                hi=random.choice([1513,1514,1515,1520])
                if hi<lo: lo,hi=hi,lo
            pat.append((lo,hi))
        pats.append(tuple(pat))
    b=brute(pats)
    cap=len(b) if random.random()<.5 else random.randint(0,20)
    sp=ExactKeySpace(pats,cap)
    c=sp.count(); exp=min(len(b),cap+1)
    if c!=exp:
        print('COUNT FAIL',trial,L,n,cap,c,exp,pats,len(b)); break
    if len(b)<=cap:
        k=sp.keys(); bset={tuple(x) for x in b}
        if set(k)!=bset:
            print('KEYS FAIL',trial,L,n,cap,pats,len(k),len(bset),sorted(k)[:5],sorted(bset)[:5]); break
else:
    print('all ok')
